<?php require_once 'auth.php';requiereRol('administrador','empleado');$rows=$conexion->query('SELECT m.*,u.nombre cliente FROM mascotas m JOIN usuario u ON u.idUsuario=m.idUsuario ORDER BY m.idMascota DESC')->fetchAll();encabezado('Registro de mascotas');?><div class="table-wrap"><table><tr><th>Cliente</th><th>Mascota</th><th>Especie</th><th>Raza</th><th>Edad</th><th>Peso</th><th>Observaciones</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['cliente'])?></td><td><?=e($r['nombre'])?></td><td><?=e($r['especie'])?></td><td><?=e($r['raza'])?></td><td><?=e($r['edad'])?></td><td><?=e($r['peso'])?></td><td><?=e($r['observaciones'])?></td></tr><?php endforeach;?></table></div><?php pie();?>